// Content with portions generated by generative AI platform
package org.eclipse.kura.core.configuration.util;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.util.Map;

import org.eclipse.kura.core.configuration.metatype.Tad;
import org.eclipse.kura.core.configuration.metatype.Tocd;
import org.eclipse.kura.core.configuration.metatype.Tscalar;
import org.junit.Test;

public class MalformedMetatypeDefaultTest {

    private static final String MALFORMED = "malformed";
    private static final String VALID = "valid";

    private final Tocd ocd = new Tocd();
    private Map<String, Object> defaults;
    private RuntimeException occurredException;

    @Test
    public void malformedIntegerDefaultIsSkipped() {
        givenAttribute(MALFORMED, Tscalar.INTEGER, 0, "abc");
        givenAttribute(VALID, Tscalar.INTEGER, 0, "5");

        whenDefaultsAreComputed();

        thenNoExceptionOccurred();
        thenDefaultIsAbsent(MALFORMED);
        thenDefaultIs(VALID, 5);
    }

    @Test
    public void multiValuedDefaultWithAMalformedValueIsSkipped() {
        givenAttribute(MALFORMED, Tscalar.LONG, 3, "1,x,3");
        givenAttribute(VALID, Tscalar.LONG, 3, "1,2,3");

        whenDefaultsAreComputed();

        thenNoExceptionOccurred();
        thenDefaultIsAbsent(MALFORMED);
        thenDefaultsAre(VALID, new Long[] { 1L, 2L, 3L });
    }

    @Test
    public void byteDefaultOutsideTheRangeOfTheTypeIsSkipped() {
        givenAttribute(MALFORMED, Tscalar.BYTE, 0, "300");

        whenDefaultsAreComputed();

        thenNoExceptionOccurred();
        thenDefaultIsAbsent(MALFORMED);
    }

    private void givenAttribute(final String id, final Tscalar type, final int cardinality, final String value) {
        final Tad attribute = new Tad();
        attribute.setId(id);
        attribute.setName(id);
        attribute.setType(type);
        attribute.setCardinality(cardinality);
        attribute.setRequired(true);
        attribute.setDefault(value);
        this.ocd.addAD(attribute);
    }

    private void whenDefaultsAreComputed() {
        try {
            this.defaults = ComponentUtil.getDefaultProperties(this.ocd, null);
        } catch (final RuntimeException e) {
            this.occurredException = e;
        }
    }

    private void thenNoExceptionOccurred() {
        assertNull(this.occurredException);
        assertNotNull(this.defaults);
    }

    private void thenDefaultIsAbsent(final String id) {
        assertFalse(this.defaults.containsKey(id));
    }

    private void thenDefaultIs(final String id, final Object value) {
        assertEquals(value, this.defaults.get(id));
    }

    private void thenDefaultsAre(final String id, final Object[] values) {
        assertArrayEquals(values, (Object[]) this.defaults.get(id));
    }
}
